using WeChatBridge.Windows.Core.Licensing;

namespace WeChatBridge.Windows.Tests;

/// <summary>
/// The shared canonical-payload test vector from §10.2.
/// <para>
/// This is the one place in the licence format where a disagreement between the
/// server and the client is invisible: the signature is perfectly valid, every field
/// parses, and every customer's Pro flag goes off at the same moment. So the vector
/// below is written out literally, byte for byte, rather than recomputed from the code
/// that is supposed to produce it — a vector generated by the implementation under test
/// proves nothing.
/// </para>
/// </summary>
public sealed class LicensingCanonicalPayloadTests
{
    /// <summary>
    /// The literal text the server and the client must both produce for
    /// <see cref="LicenseToken.CurrentSchemaVersion"/>. <c>\n</c> line endings, no trailing
    /// newline, 109 bytes.
    /// <para>
    /// <c>ReplaceLineEndings</c> is not decoration. This repository has no
    /// <c>.gitattributes</c> and <c>core.autocrlf</c> is on, so a checkout on Windows
    /// hands the compiler this literal with <c>\r\n</c> — and a raw string literal
    /// keeps whatever the file has. The signature is still perfectly valid and every
    /// field still parses; the client simply never agrees with the server. Normalising
    /// here keeps the vector hand-written (still not generated from the implementation
    /// under test) while making it independent of how it was checked out.
    /// </para>
    /// </summary>
    public static string SharedCanonicalVector { get; } = """
        wechatbridge.license.v1
        v=1
        sub=Zx8Kq3nT7pQ1mR4vW9yB0
        plan=buyout
        iat=1772323200
        nbf=-
        exp=-
        ent=EXPORT,SCENE
        """.ReplaceLineEndings("\n");

    /// <summary>
    /// SHA-256 of <see cref="SharedCanonicalVector"/>'s UTF-8 bytes, no trailing newline.
    /// A server can check its canonicaliser against this one number without linking to
    /// any of this code.
    /// </summary>
    public const string SharedCanonicalVectorSha256 =
        "0897d84321f6816e2600528641592e309729460e332c8922bbbc03dbdc920306";

    private static LicenseCanonicalPayload Vector() =>
        new(
            LicenseToken.CurrentSchemaVersion,
            "Zx8Kq3nT7pQ1mR4vW9yB0",
            "buyout",
            TestTime.IssuedAt,
            null,
            null,
            ["EXPORT", "SCENE"]);

    [Fact]
    public void TheClientProducesTheSharedVectorExactly()
    {
        Assert.Equal(SharedCanonicalVector, Vector().Canonical);
    }

    [Fact]
    public void TheSharedVectorHasTheDocumentedShapeAndDigest()
    {
        var bytes = Vector().Bytes;

        // 109 bytes, and the last one is not a newline — a trailing newline would make
        // the server's copy differ from the client's by exactly one byte.
        Assert.Equal(109, bytes.Length);
        Assert.NotEqual((byte)'\n', bytes[^1]);

        Assert.Equal(SharedCanonicalVectorSha256, Convert.ToHexStringLower(System.Security.Cryptography.SHA256.HashData(bytes)));
    }

    [Fact]
    public void TheLineCountIsFixedEvenWhenEveryOptionalFieldIsAbsent()
    {
        Assert.Equal(LicenseToken.CanonicalLineCount, SharedCanonicalVector.Split('\n').Length);
        Assert.Equal(SharedCanonicalVector.Split('\n').Length, Vector().Canonical.Split('\n').Length);
    }

    [Fact]
    public void ASignatureOverTheSharedConstantVerifies()
    {
        using var keys = new TestSigningKey();
        var envelope = new LicenseEnvelope
        {
            SchemaVersion = LicenseToken.CurrentSchemaVersion,
            Subject = "Zx8Kq3nT7pQ1mR4vW9yB0",
            Plan = "buyout",
            IssuedAt = TestTime.IssuedAt,
            NotBefore = null,
            ExpiresAt = null,
            Entitlements = ["EXPORT", "SCENE"],
        };
        var signature = keys.Sign(LicenseCanonicalPayload.From(envelope));

        // Signed over the hand-written constant, not over the implementation's output.
        var verification = keys.Verifier().Verify(envelope with { Signature = signature }, TestTime.Now, TimeSpan.Zero);

        Assert.True(verification.IsValid, verification.Failure);
    }

    [Theory]
    [InlineData("entitlement order")]
    [InlineData("blank entitlement")]
    [InlineData("case")]
    public void EntitlementsThatMeanTheSameThingProduceTheSameBytes(string scenario)
    {
        var baseline = new LicenseCanonicalPayload(
            1, "sub", "buyout", TestTime.IssuedAt, null, null, ["EXPORT", "SCENE"]);

        IReadOnlyList<string> reordered = scenario switch
        {
            // Any set iteration hands the bits over in an arbitrary order; a signature
            // taken over an unsorted list fails on the client and only there.
            "entitlement order" => ["SCENE", "EXPORT"],
            "blank entitlement" => ["EXPORT", "  ", "SCENE"],
            _ => ["export", "Scene"],
        };

        var other = new LicenseCanonicalPayload(1, "sub", "buyout", TestTime.IssuedAt, null, null, reordered);

        Assert.Equal(baseline.Bytes, other.Bytes);
        Assert.Equal("EXPORT,SCENE", other.NormalizedEntitlements);
    }

    [Fact]
    public void ARepeatedEntitlementBitIsSignedOnce()
    {
        var payload = new LicenseCanonicalPayload(1, "sub", "buyout", TestTime.IssuedAt, null, null, ["EXPORT", "EXPORT"]);

        Assert.Equal("EXPORT", payload.NormalizedEntitlements);
    }

    [Fact]
    public void AnEmptyEntitlementListIsTheSameSentinelAsAnAbsentOne()
    {
        var none = new LicenseCanonicalPayload(1, "sub", "buyout", TestTime.IssuedAt, null, null, []);
        var blanks = new LicenseCanonicalPayload(1, "sub", "buyout", TestTime.IssuedAt, null, null, ["  ", ""]);

        Assert.Equal(LicenseCanonicalPayload.Absent, none.NormalizedEntitlements);
        Assert.Equal(none.Bytes, blanks.Bytes);
    }

    [Fact]
    public void TimestampsAreSignedAsUnixSecondsRegardlessOfTheInputOffset()
    {
        var utc = new DateTimeOffset(2026, 3, 1, 0, 0, 0, TimeSpan.Zero);
        var shifted = new DateTimeOffset(2026, 3, 1, 8, 0, 0, TimeSpan.FromHours(8));

        Assert.Equal("iat=1772323200", new LicenseCanonicalPayload(1, "s", "p", utc, null, null, []).Canonical
            .Split('\n')[4]);
        // A server running in a local zone must still produce the same bytes.
        Assert.Equal(
            new LicenseCanonicalPayload(1, "s", "p", utc, null, null, []).Bytes,
            new LicenseCanonicalPayload(1, "s", "p", shifted, null, null, []).Bytes);
    }

    [Fact]
    public void SubSecondPrecisionIsDroppedSoTwoRoundTripsAgree()
    {
        var whole = new DateTimeOffset(2026, 3, 1, 0, 0, 0, TimeSpan.Zero);
        var lateInTheSecond = whole.AddMilliseconds(999);

        // JSON keeps sub-second precision and the canonical form does not, so the
        // signature must depend only on the second the server serialised to.
        Assert.NotEqual(whole, lateInTheSecond);
        Assert.Equal(
            new LicenseCanonicalPayload(1, "s", "p", whole, null, null, []).Bytes,
            new LicenseCanonicalPayload(1, "s", "p", lateInTheSecond, null, null, []).Bytes);
    }

    [Fact]
    public void TheDomainSeparatorIsOnItsOwnLineAndCannotBeConfusedWithAPlanName()
    {
        var payload = new LicenseCanonicalPayload(1, "sub", LicenseCanonicalPayload.DomainSeparator, TestTime.IssuedAt, null, null, []);

        Assert.StartsWith(LicenseCanonicalPayload.DomainSeparator + "\nv=", payload.Canonical, StringComparison.Ordinal);
    }
}

/// <summary>Base64url is the encoding for every field that is also inside the signed bytes.</summary>
public sealed class LicensingBase64UrlTests
{
    [Theory]
    [InlineData(new byte[] { 0xFB }, "-w")]           // base64 "+w"
    [InlineData(new byte[] { 0xFF, 0xFF, 0xFE }, "___-")]  // base64 "///+"
    public void UnpaddedBase64UrlNeverEmitsPlusSlashOrEquals(byte[] input, string expected)
    {
        var encoded = Base64Url.Encode(input);

        Assert.Equal(expected, encoded);
        Assert.DoesNotContain('=', encoded);
        Assert.DoesNotContain('+', encoded);
        Assert.DoesNotContain('/', encoded);
    }

    [Theory]
    [InlineData(1)]
    [InlineData(2)]
    [InlineData(16)]
    [InlineData(32)]
    [InlineData(64)]
    public void EveryLengthRoundTrips(int length)
    {
        var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(length);

        Assert.True(Base64Url.TryDecode(Base64Url.Encode(bytes), out var decoded, length));
        Assert.Equal(bytes, decoded);
    }

    [Theory]
    [InlineData(null)]
    [InlineData("")]
    [InlineData("a")]        // a single character cannot be base64 of anything
    [InlineData("!!!!")]
    [InlineData("AAAAA")]     // length % 4 == 1 is not a valid base64 length
    public void MalformedInputDecodesToFalseRatherThanThrowing(string? text)
    {
        Assert.False(Base64Url.TryDecode(text, out var bytes));
        Assert.Empty(bytes);
    }

    [Fact]
    public void TheWrongByteLengthIsRejected()
    {
        var encoded = Base64Url.Encode(new byte[64]);

        Assert.False(Base64Url.TryDecode(encoded, out _, LicenseToken.SignatureLength + 1));
        Assert.True(Base64Url.TryDecode(encoded, out _, LicenseToken.SignatureLength));
    }
}
